-- composition of rule kernels duplicate_groups x redundant_order (duckdb), template cte_twice
WITH ka AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT 'epoch'::timestamptz AS c0 FROM (SELECT 46 AS c0, 0 AS c1 ORDER BY ALL) AS a1 GROUP BY ROLLUP (a1.c1, a1.c0)), kb AS (SELECT ((COUNT (DISTINCT a1.c1) % 1000)::int - 1) AS c0, a1.c1 AS c1, 'A'::text AS c2, 1::bigint AS c3 FROM tl AS a1 GROUP BY a1.c1) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT 'epoch'::timestamptz AS c0 FROM (SELECT 46 AS c0, 0 AS c1 ORDER BY ALL) AS a1 GROUP BY ROLLUP (a1.c1, a1.c0)) AS ka) + (SELECT count(*) FROM (SELECT ((COUNT (DISTINCT a1.c1) % 1000)::int - 1) AS c0, a1.c1 AS c1, 'A'::text AS c2, 1::bigint AS c3 FROM tl AS a1 GROUP BY a1.c1) AS kb)
